                              ('📜 律法与智慧诗', '#5ab0ff', ['1、19、119（律法）', '37、49、73（智慧）']),
                              ('💔 忏悔诗（七篇）', '#ff7eb6', ['6、32、38、51、102、130、143']),
                              ('⛰️ 锡安与上行诗', '#2fd3d3', ['46、48、84、87', '120–134 上行之诗']),
